.darma-loader-darma-b14-key-turn { --accent: var(--loader-color, #b45309); --accent-2: var(--loader-secondary-color, #94a3b8); width: var(--loader-size, 92px); height: var(--loader-size, 92px); position: relative; border-radius: 50%; background: color-mix(in srgb, #fff 62%, var(--accent-2)); box-shadow: inset 0 0 0 calc(var(--loader-size, 92px) * .05) color-mix(in srgb, #000 20%, var(--accent-2)); }
.darma-loader-darma-b14-key-turn::after { content: ''; position: absolute; top: 30%; left: 41%; width: 18%; height: 34%; border-radius: 50% 50% 20% 20%; background: color-mix(in srgb, #000 56%, var(--accent-2)); }
.darma-loader-darma-b14-key-turn .darma-loader-darma-b14-key-turn__key { position: absolute; z-index: 2; top: 16%; left: calc(50% - var(--loader-size, 92px) * .035); width: calc(var(--loader-size, 92px) * .07); height: calc(var(--loader-size, 92px) * .66); transform-origin: 50% 50%; border-radius: 999px; background: linear-gradient(90deg, color-mix(in srgb, #fff 40%, var(--accent)), var(--accent)); animation: darma-loader-darma-b14-key-turn-turn-key calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.5, 0, .3, 1) infinite; }
.darma-loader-darma-b14-key-turn .darma-loader-darma-b14-key-turn__key::before { content: ''; position: absolute; top: calc(var(--loader-size, 92px) * -.14); left: calc(var(--loader-size, 92px) * -.06); width: calc(var(--loader-size, 92px) * .19); height: calc(var(--loader-size, 92px) * .19); border-radius: 50%; border: calc(var(--loader-size, 92px) * .034) solid var(--accent); }
.darma-loader-darma-b14-key-turn .darma-loader-darma-b14-key-turn__key::after { content: ''; position: absolute; bottom: calc(var(--loader-size, 92px) * .03); left: 86%; width: calc(var(--loader-size, 92px) * .1); height: calc(var(--loader-size, 92px) * .18); background: var(--accent); clip-path: polygon(0 0, 100% 0, 100% 30%, 38% 30%, 38% 58%, 100% 58%, 100% 100%, 0 100%); }
@keyframes darma-loader-darma-b14-key-turn-turn-key { 0%, 20% { transform: rotate(0deg); } 48%, 70% { transform: rotate(92deg); } 92%, 100% { transform: rotate(0deg); } }

